# ---------------------------------------------------------------- layout ----
PIECES = [
    ("VERCEL", [(0, 0), (0, 1), (0, 2), (1, 2)]),
    ("DOCKER", [(1, 0), (1, 1), (2, 1), (3, 1)]),
    ("GITHUB ACTIONS", [(2, 0), (3, 0), (4, 0), (5, 0)]),
    ("PRISMA", [(4, 1), (5, 1), (6, 0), (6, 1)]),
    ("SQLITE", [(7, 0), (8, 0), (8, 1), (8, 2)]),
    ("VITEST", [(9, 0), (9, 1), (10, 1), (10, 2)]),
    ("PLAYWRIGHT", [(10, 0), (11, 0), (11, 1), (11, 2)]),
    ("TYPST", [(12, 0), (12, 1), (13, 0), (13, 1)]),
    ("LANGCHAIN", [(6, 2), (6, 3), (7, 1), (7, 2)]),
    ("LANGGRAPH", [(2, 2), (2, 3), (2, 4), (3, 2)]),
    ("OLLAMA", [(3, 3), (4, 2), (4, 3), (5, 2)]),
    ("FASTAPI", [(9, 2), (9, 3), (10, 3), (11, 3)]),
    ("PYTORCH", [(12, 2), (12, 3), (12, 4), (13, 2)]),
    ("MEDIAPIPE", [(0, 3), (0, 4), (1, 3), (1, 4)]),
    ("NODE.JS", [(5, 3), (5, 4), (6, 4), (6, 5)]),
    ("TAILWIND", [(7, 3), (7, 4), (7, 5), (8, 5)]),
    ("REACT", [(8, 3), (8, 4), (9, 4), (9, 5)]),
    ("NEXT.JS", [(12, 5), (13, 3), (13, 4), (13, 5)]),
    ("HTML/CSS", [(3, 4), (4, 4), (4, 5), (5, 5)]),
    ("JAVA", [(10, 4), (11, 4), (11, 5), (11, 6)]),
    ("SWIFT", [(0, 5), (0, 6), (1, 5), (2, 5)]),
    ("JAVASCRIPT", [(2, 6), (2, 7), (3, 5), (3, 6)]),
    ("TYPESCRIPT", [(9, 6), (10, 5), (10, 6), (10, 7)]),
    ("PYTHON", [(5, 6), (6, 6), (6, 7), (7, 6)]),
]


# --------------------------------------------------------------- helpers ----
def shade(hexc, f):
    h = hexc.lstrip("#")
    r, g, b = (int(h[i:i + 2], 16) for i in (0, 2, 4))
    if f >= 0:
        r, g, b = (int(v + (255 - v) * f) for v in (r, g, b))
    else:
        r, g, b = (int(v * (1 + f)) for v in (r, g, b))
    return f"#{r:02x}{g:02x}{b:02x}"


def luminance(hexc):
    h = hexc.lstrip("#")
    r, g, b = (int(h[i:i + 2], 16) for i in (0, 2, 4))
    return 0.2126 * r + 0.7152 * g + 0.0722 * b


def px(c, r):
    return PAD_X + c * CELL, PAD_TOP + (MAXH - 1 - r) * CELL


def cell_svg(c, r, base):
    x, y = px(c, r)
    b, s = 7, CELL
    return (
        f'<rect x="{x}" y="{y}" width="{s}" height="{s}" fill="{base}"/>'
        f'<polygon points="{x},{y} {x+s},{y} {x+s-b},{y+b} {x+b},{y+b}" fill="{shade(base, .35)}"/>'
        f'<polygon points="{x},{y} {x+b},{y+b} {x+b},{y+s-b} {x},{y+s}" fill="{shade(base, .15)}"/>'
        f'<polygon points="{x+s},{y} {x+s},{y+s} {x+s-b},{y+s-b} {x+s-b},{y+b}" fill="{shade(base, -.15)}"/>'
        f'<polygon points="{x},{y+s} {x+s},{y+s} {x+s-b},{y+s-b} {x+b},{y+s-b}" fill="{shade(base, -.35)}"/>'
    )


def outline_svg(cells):
    cs = set(cells)
    out = []
    for c, r in cells:
        x, y = px(c, r)
        edges = []
        if (c, r + 1) not in cs: edges.append((x, y, x + CELL, y))
        if (c, r - 1) not in cs: edges.append((x, y + CELL, x + CELL, y + CELL))
        if (c - 1, r) not in cs: edges.append((x, y, x, y + CELL))
        if (c + 1, r) not in cs: edges.append((x + CELL, y, x + CELL, y + CELL))
        for x1, y1, x2, y2 in edges:
            out.append(f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="#050814" stroke-width="5" stroke-linecap="square"/>')
    return "".join(out)


def _glyph(slug, x, y, size, color, shadow):
    t = f'translate({x:.1f},{y:.1f}) scale({size / 24:.4f})'
    d = ICONS[slug]
    return (f'<path transform="{t}" d="{d}" fill="{shadow}" fill-opacity=".4" stroke="{shadow}" '
            f'stroke-opacity=".4" stroke-width="{2.2 * 24 / size:.2f}" stroke-linejoin="round"/>'
            f'<path transform="{t}" d="{d}" fill="{color}"/>')


def icon_svg(name, cx, cy, color, shadow):
    """Brand logo centred on (cx, cy) in a 30px box; 'a+b' draws two logos side by side."""
    parts = name.split("+")
    if len(parts) == 1:
        return _glyph(name, cx - 15, cy - 15, 30, color, shadow)
    s = 20
    return "".join(_glyph(p, cx - s - 1 + k * (s + 2), cy - s / 2, s, color, shadow) for k, p in enumerate(parts))


def label_and_icon(label, cells, text_color, shadow):
    """Label goes in the piece's widest row; the icon goes in the cell farthest from it."""
    rows = {}
    for c, r in cells:
        rows.setdefault(r, []).append(c)
    r_best = max(rows, key=lambda r: (len(rows[r]), -r))
    cs = sorted(rows[r_best])
    others = [(c, r) for c, r in cells if r != r_best]
    row_cx = PAD_X + (cs[0] + cs[-1] + 1) / 2 * CELL
    if others:
        icon_cell = max(others, key=lambda cr: abs(PAD_X + (cr[0] + .5) * CELL - row_cx))
        label_cells = cs
    else:  # straight piece: icon takes an end cell, label centres over the rest
        icon_cell = (cs[0], r_best)
        label_cells = cs[1:]
    cx = PAD_X + (label_cells[0] + label_cells[-1] + 1) / 2 * CELL
    cy = PAD_TOP + (MAXH - 1 - r_best) * CELL + CELL / 2
    run_px = len(label_cells) * CELL - 14

    lines = [label]
    if " " in label and len(label) * 0.62 * 14 > run_px:
        lines = label.split(" ")
    fs = min(14, run_px / (max(len(l) for l in lines) * 0.66))
    style = f'fill:{text_color};stroke:{shadow};stroke-opacity:.45'
    if len(lines) == 1:
        text = f'<text x="{cx:.1f}" y="{cy:.1f}" font-size="{fs:.1f}" style="{style}">{label}</text>'
    else:
        text = (f'<text x="{cx:.1f}" y="{cy - fs * .6:.1f}" font-size="{fs:.1f}" style="{style}">{lines[0]}</text>'
                f'<text x="{cx:.1f}" y="{cy + fs * .6:.1f}" font-size="{fs:.1f}" style="{style}">{lines[1]}</text>')
    ix = PAD_X + (icon_cell[0] + .5) * CELL
    iy = PAD_TOP + (MAXH - 1 - icon_cell[1]) * CELL + CELL / 2
    return text, ix, iy


# ------------------------------------------------------------- animation ----
def plan_waves():
    """Group pieces into waves of 2-3 that fall together.

    Every piece spawns just above the well and drops one row per tick. A piece is only
    released once everything beneath it has landed, so it always falls into free space and
    lands on something solid. Returns ({index: (start_time, rows_to_fall)}, end_time).
    """
    n = len(PIECES)
    where = {}
    for i, (_, cells) in enumerate(PIECES):
        for cell in cells:
            where[cell] = i
    below = [set() for _ in range(n)]
    for i, (_, cells) in enumerate(PIECES):
        for c, r in cells:
            for rr in range(r):
                j = where.get((c, rr))
                if j is not None and j != i:
                    below[i].add(j)
    low = lambda i: (min(r for _, r in PIECES[i][1]), min(c for c, _ in PIECES[i][1]))

    rng = random.Random(SEED)
    placed, remaining, plan = set(), set(range(n)), {}
    t = START_DELAY
    while remaining:
        ready = sorted((i for i in remaining if below[i] <= placed), key=low)
        if not ready:
            raise SystemExit("layout has interlocking pieces that cannot be dropped in order")
        pool = ready[:6]
        chosen = rng.sample(pool, min(rng.choice([2, 3]), len(pool)))
        wave_end = t
        for k, i in enumerate(sorted(chosen, key=low)):
            rows = MAXH + 1 - min(r for _, r in PIECES[i][1])   # spawn fully hidden, one row above the well
            start = t + k * STAGGER
            plan[i] = (start, rows)
            wave_end = max(wave_end, start + rows * STEP)
        placed |= set(chosen)
        remaining -= set(chosen)
        t = wave_end + WAVE_PAUSE
    return plan, t


def keyframes(i, start, rows, total):
    """One shared timeline for every piece: it waits above the well, then drops one row per tick."""
    pct = lambda s: f"{s / total * 100:.3f}%"
    hold = "animation-timing-function:step-end"
    stops = [f"0%{{transform:translateY({-rows * CELL}px);{hold}}}"]
    for k in range(rows + 1):
        stops.append(f"{pct(start + k * STEP)}{{transform:translateY({-(rows - k) * CELL}px);{hold}}}")
    stops.append("100%{transform:translateY(0)}")
    return f"@keyframes f{i}{{{''.join(stops)}}}"


# ----------------------------------------------------------------- build ----
def build():
    cells = [cell for _, cs in PIECES for cell in cs]
    board = {(c, r) for c in range(COLS) for r in range(HEIGHTS[c])}
    assert len(cells) == len(set(cells)) and set(cells) == board, "layout leaves gaps or overlaps"
    plan, end = plan_waves()
    total = end + HOLD
    out = [
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}" role="img" aria-label="Tetris-style graphic of my tech stack">',
        '<title>Tech stack</title>',
        '<style>'
        'text{font-family:"Segoe UI",Verdana,Helvetica,Arial,sans-serif;font-weight:800;stroke-width:3px;paint-order:stroke;'
        'text-anchor:middle;dominant-baseline:central;letter-spacing:.4px}'
        '.t{font-size:30px;text-anchor:start;fill:#fff;stroke:none;letter-spacing:1px}'
        '@media (prefers-reduced-motion:reduce){.p{animation:none!important}}'
        + ''.join(keyframes(i, *plan[i], total) for i in range(len(PIECES))) +
        '</style>',
        f'<defs><clipPath id="well"><rect x="0" y="{PAD_TOP - 4}" width="{W}" height="{H - PAD_TOP + 4}"/></clipPath></defs>',
        f'<rect width="{W}" height="{H}" rx="18" fill="#0b1020"/>',
        f'<text class="t" x="{PAD_X}" y="52">STACK</text>',
        f'<line x1="{PAD_X}" y1="74" x2="{W - PAD_X}" y2="74" stroke="#2a3558" stroke-width="2"/>',
    ]
    for c in range(COLS):
        for r in range(MAXH):
            x, y = px(c, r)
            out.append(f'<rect x="{x}" y="{y}" width="{CELL}" height="{CELL}" fill="none" stroke="#141b33"/>')

    out.append('<g clip-path="url(#well)">')
    for i, (label, cells) in enumerate(PIECES):
        base, icon = TECH[label]
        first = sorted(cells)[0]
        dark_text = luminance(base) > 165
        text_color = "#0b1020" if dark_text else "#ffffff"
        shadow = "#ffffff" if dark_text else "#000000"
        style = f'animation:f{i} {total:.2f}s linear 1 both'
        cls = "p"
        g = [f'<g class="{cls}" style="{style}">']
        for c, r in cells:
            color = FIRST_CELL_COLOR.get(label, base) if (c, r) == first else base
            g.append(cell_svg(c, r, color))
        g.append(outline_svg(cells))
        text, ix, iy = label_and_icon(label, cells, text_color, shadow)
        g.append(icon_svg(icon, ix, iy, text_color, shadow))
        g.append(text)
        g.append('</g>')
        out.append("".join(g))
    out.append('</g></svg>')
    return "\n".join(out), end


if __name__ == "__main__":
    svg, total = build()
    path = sys.argv[1] if len(sys.argv) > 1 else "stack.svg"
    with open(path, "w") as f:
        f.write(svg)
    print(f"wrote {path} ({len(svg)} bytes), animation ~{total:.1f}s")
